/** Shape of public/data/dataset.json (generated by tools/xlsx_to_json.py from the Power BI workbook). */
export interface Dataset {
  settings: {
    dataAsOf: string;
    monthlyBudgetTnd: number;
    satisfactionThreshold: number;
    adoptionThreshold: number;
    responseTimeThresholdSec: number;
  };
  calendar: { start: string; end: string };
  departments: { id: number; name: string; short: string; headcount: number; order: number }[];
  themes: { id: number; name: string; short: string; color: string; order: number }[];
  documents: { id: number; title: string; category: string }[];
  keywords: string[];
  userCount: number;
  /** Column-oriented fact table; index i is one question. `day` = days since calendar.start, `fb` = -1 when no vote. */
  questions: {
    day: number[];
    user: number[];
    dept: number[];
    theme: number[];
    kw: number[];
    rt: number[];
    err: number[];
    cost: number[];
    fb: number[];
    conv: number[];
  };
  /** `q` = row index in `questions`. */
  citations: { q: number[]; doc: number[] };
}
